sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float shadowHue;
uniform float shadowAmount;
uniform float highlightHue;
uniform float highlightAmount;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
float3 chroma(float hue) {
    float3 k = clamp(abs(fract(hue / 360.0 + float3(1.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
    return k - luma(k);
}
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return c;
    float3 base = float3(c.rgb) / float(c.a);
    float l = luma(base);
    float reach = 2.0 * min(l, 1.0 - l);
    float3 dark = clamp(l + chroma(shadowHue) * reach, 0.0, 1.0);
    float3 light = clamp(l + chroma(highlightHue) * reach, 0.0, 1.0);
    float3 rgb = mix(base, dark, clamp(shadowAmount, 0.0, 1.0) * (1.0 - l));
    rgb = mix(rgb, light, clamp(highlightAmount, 0.0, 1.0) * l);
    return half4(half3(clamp(rgb, 0.0, 1.0)) * c.a, c.a);
}
